ax1.text(0.02, 0.98, textstr, transform=ax1.transAxes, fontsize=10, verticalalignment='top', bbox=props)
interp_text = 'VALUTAZIONE:\n• MAP costantemente <65 mmHg = perfusione inadeguata\n• FC stabile (bassa volatilità) nonostante ipotensione\n• Tachicardia compensatoria assente suggerisce:\n  - Effetto beta-bloccante o\n  - Disfunzione cardiaca o\n  - Shock settico avanzato'
props2 = dict(boxstyle='round', facecolor='lightyellow', alpha=0.9)
ax1.text(0.98, 0.02, interp_text, transform=ax1.transAxes, fontsize=9, verticalalignment='bottom', horizontalalignment='right', bbox=props2)
lines1, labels1 = ax1.get_legend_handles_labels()
lines2, labels2 = ax2.get_legend_handles_labels()
ax1.legend(lines1 + lines2, labels1 + labels2, loc='upper right', fontsize=9)
plt.tight_layout()
save_plot('hr_map_dual_axis_timeseries.png')
aligned_hr = []
aligned_map = []
for map_t, map_v in zip(map_times, map_values):
    min_diff = float('inf')
    closest_hr = None
    for hr_t, hr_v in heart_rate:
        diff = abs((map_t - hr_t).total_seconds())
        if diff < min_diff:
            min_diff = diff
            closest_hr = hr_v
    if min_diff < 300 and closest_hr is not None:
        aligned_hr.append(closest_hr)
        aligned_map.append(map_v)
if len(aligned_hr) >= 5:
    correlation, p_value = stats.pearsonr(aligned_hr, aligned_map)
else:
    correlation = np.nan
    p_value = np.nan
hypotensive_count = sum((1 for m in map_values if m < 65))
hypotensive_pct = hypotensive_count / len(map_values) * 100 if map_values else 0
hr_during_hypotension = [aligned_hr[i] for i in range(len(aligned_map)) if aligned_map[i] < 65]
mean_hr_hypotensive = np.mean(hr_during_hypotension) if hr_during_hypotension else np.nan
result = {'map_mean': float(np.mean(map_values)), 'map_min': float(np.min(map_values)), 'map_max': float(np.max(map_values)), 'hr_mean': float(np.mean(hr_values)), 'hr_std': float(np.std(hr_values)), 'hr_map_correlation': float(correlation) if not np.isnan(correlation) else None, 'hr_map_correlation_pvalue': float(p_value) if not np.isnan(p_value) else None, 'hypotensive_episodes_pct': float(hypotensive_pct), 'mean_hr_during_hypotension': float(mean_hr_hypotensive) if not np.isnan(mean_hr_hypotensive) else None, 'shock_index': shock_index, 'qsofa_score': qsofa_score}
interpretation = f'ANALISI TEMPORALE FC-MAP: MAP criticamente bassa (media {np.mean(map_values):.1f} mmHg, {hypotensive_pct:.0f}% delle letture <65 mmHg) indicando un inadeguato e sostenuto apporto di perfusione agli organi. La frequenza cardiaca rimane inappropriatamente stabile (media {np.mean(hr_values):.1f} bpm, SD {np.std(hr_values):.1f}) senza tachicardia compensatoria durante gli episodi ipotensivi (FC media durante ipotensione: {mean_hr_hypotensive:.1f} bpm). Correlazione FC-MAP: {correlation:.2f}. Questa risposta cronotropa attenuata nel contesto di sepsi con Indice di Shock {shock_index:.2f} e qSOFA {qsofa_score}/3 suggerisce un possibile effetto farmacologico (nessun beta-bloccante elencato, ma anticoagulanti), una disfunzione cardiaca sottostante (cardiomiopatia, FA) o uno shock distributivo avanzato con insufficienza autonomica. PREOCCUPAZIONE CLINICA: L\'assenza di tachicardia compensatoria è un segno infausto nello shock settico.'

